#!/usr/bin/env bash
# Idempotent builds needed before the dev processes and the tests: generated types, ui build. No containers.
# Usage: npm run dev-setup
set -euo pipefail
cd "$(dirname "$0")/.."

[ -d api/config/type/.type ] && [ -d ui/src/components/vjsf ] || npm run build-types
# served by the api, and vue-tsc needs the ui/dts files generated by the ui build. A production build, like the image's,
# whatever NODE_ENV the dev processes use
[ -f ui/dist/index.html ] || NODE_ENV=production npm -w ui run build
